def detach_retired_lots(apps, schema_editor):
    """Keep any historical rows without tying them to active holdings."""
    lot = apps.get_model("Shares", "PortfolioLots")
    if lot._meta.db_table in schema_editor.connection.introspection.table_names():
        old_field = lot._meta.get_field("portfolio_id")
        detached_field = copy(old_field)
        detached_field.db_constraint = False
        schema_editor.alter_field(lot, old_field, detached_field)


def preserve_opening_balances(apps, schema_editor):
    """
    Merge duplicate portfolio aggregates without inventing
    prices for historical transactions.

    Preserve opening balances and mark existing transactions
    as legacy records.
    """

    Holding = apps.get_model("Shares", "Portfolios")
    Transaction = apps.get_model("Shares", "Transactions")

    database = schema_editor.connection.alias

    # Find duplicate holdings belonging to the same
    # user and company.
    groups = (
        Holding.objects.using(database)
        .values("user_id", "company_id")
        .annotate(count=models.Count("pk"))
        .filter(count__gt=1)
    )

    # Merge duplicate portfolio holdings.
    for group in groups.iterator():

        duplicates = list(
            Holding.objects.using(database)
            .filter(
                user_id=group["user_id"],
                company_id=group["company_id"],
            )
            .order_by("created_at", "pk")
        )

        keeper = duplicates[0]

        keeper.number_of_shares = sum(
            item.number_of_shares or 0
            for item in duplicates
        )

        keeper.total_cost = sum(
            (
                Decimal(str(item.total_cost or 0))
                for item in duplicates
            ),
            Decimal("0"),
        ).quantize(
            Decimal("0.01"),
            rounding=ROUND_HALF_UP,
        )

        keeper.save(
            using=database,
            update_fields=[
                "number_of_shares",
                "total_cost",
            ],
        )

        # Remove duplicate records after merging.
        duplicate_ids = [
            item.pk
            for item in duplicates[1:]
        ]

        Holding.objects.using(database).filter(
            pk__in=duplicate_ids
        ).delete()

    # Preserve the existing opening holdings.
    for holding in (
        Holding.objects.using(database).all().iterator()
    ):

        holding.opening_number_of_shares = (
            holding.number_of_shares or 0
        )

        holding.opening_total_cost = Decimal(
            str(holding.total_cost or 0)
        ).quantize(
            Decimal("0.01"),
            rounding=ROUND_HALF_UP,
        )

        holding.ledger_initialized = True

        holding.save(
            using=database,
            update_fields=[
                "opening_number_of_shares",
                "opening_total_cost",
                "ledger_initialized",
            ],
        )

    # Mark all existing transaction records as legacy.
    Transaction.objects.using(database).all().update(
        is_legacy=True
    )


